package com.ruanzhu.doorhandle.module.ai.model;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.ruanzhu.doorhandle.common.BusinessException;
import com.ruanzhu.doorhandle.contracts.security.BusinessUserDirectory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.annotation.Isolation;
import java.time.*;
import java.util.*;

/** Per-model observations and Java provider attempts. Never infer the provider's live balance. */
@Service
@ConditionalOnProperty(prefix="app.model-budget",name="enabled",havingValue="true")
@Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED)
public class ModelBudgetService {
    public static class Exhausted extends RuntimeException { public Exhausted(String message){super(message);} }
    private final JdbcTemplate jdbc;private final BusinessUserDirectory users;private final ObjectMapper json;
    public ModelBudgetService(JdbcTemplate jdbc,BusinessUserDirectory users,ObjectMapper json){this.jdbc=jdbc;this.users=users;this.json=json;}
    private static LocalDateTime date(Object value){return value instanceof java.sql.Timestamp timestamp?timestamp.toLocalDateTime():value instanceof LocalDateTime time?time:null;}
    private BusinessUserDirectory.Identity lockedSupervisor(){var actor=supervisor();actor=users.lockCurrent(actor.userId(),actor.username());if(!actor.supervisor())throw new BusinessException(403,"当前账号已无主管权限");return actor;}
    private List<Map<String,Object>> rows(String sql,Object... arguments){return jdbc.query(sql,com.ruanzhu.doorhandle.common.LocalDateTimeRow::read,arguments);}
    private Map<String,Object> row(String sql,Object... arguments){var rows=rows(sql,arguments);if(rows.size()!=1)throw new IllegalStateException("数据记录未完整读取");return rows.get(0);}
    private static LocalDateTime now(){return LocalDateTime.now(ZoneOffset.UTC);}
    private BusinessUserDirectory.Identity supervisor(){var actor=users.authenticated();actor=users.current(actor.userId(),actor.username());if(!actor.supervisor())throw new BusinessException(403,"仅主管可管理模型额度");return actor;}
    private static void validate(String id){if(id==null||!id.matches("(dashscope|deepseek|openai):[A-Za-z0-9._/-]{1,140}"))throw new BusinessException(400,"模型标识格式不正确");}
    // An existing row must acquire an exclusive lock directly. INSERT IGNORE would
    // give concurrent writers shared locks that deadlock on the later FOR UPDATE.
    private void ensure(String id){validate(id);jdbc.update("INSERT INTO agent_model_budget(model_id,total_tokens,warning_percent,free_only,version,updated_at) VALUES(?,NULL,80,TRUE,1,?) ON DUPLICATE KEY UPDATE model_id=agent_model_budget.model_id",id,now());}
    public List<Map<String,Object>> overview(){supervisor();var rows=rows("SELECT * FROM agent_model_budget ORDER BY model_id LIMIT 300");for(var row:rows){String id=row.get("model_id").toString();var summary=row("SELECT COUNT(*) AS attempts,COALESCE(SUM(CASE WHEN input_tokens IS NOT NULL AND output_tokens IS NOT NULL THEN input_tokens+output_tokens ELSE 0 END),0) AS reportedTokens,COALESCE(SUM(CASE WHEN input_tokens IS NULL OR output_tokens IS NULL THEN 1 ELSE 0 END),0) AS unknownAttempts,COALESCE(SUM(CASE WHEN status='STARTED' THEN 1 ELSE 0 END),0) AS activeAttempts FROM agent_model_budget_attempt WHERE model_id=?",id);row.put("usage",summary);var observations=rows("SELECT id,remaining_tokens,observed_at,source_note,created_at FROM agent_model_budget_observation WHERE model_id=? ORDER BY observed_at DESC,id DESC LIMIT 1",id);row.put("providerObservation",observations.isEmpty()?null:observations.get(0));
            String alert="UNCONFIGURED";Long total=number(row.get("total_tokens"));long known=((Number)summary.get("reportedTokens")).longValue(),unknown=((Number)summary.get("unknownAttempts")).longValue();
            Long lastRemaining=observations.isEmpty()?null:((Number)observations.get(0).get("remaining_tokens")).longValue();
            if(total!=null){alert=unknown>0?"USAGE_INCOMPLETE":known>=total?"LOCAL_LIMIT_REACHED":known*100.0>=total*((Number)row.get("warning_percent")).intValue()?"LOCAL_WARNING":"LOCAL_NORMAL";}
            if(lastRemaining!=null&&total!=null&&lastRemaining*100.0<=total*(100-((Number)row.get("warning_percent")).intValue()))alert="LAST_OBSERVATION_WARNING";if(lastRemaining!=null&&lastRemaining==0)alert="LAST_OBSERVATION_EXHAUSTED";
            if(date(row.get("expires_at"))!=null&&!date(row.get("expires_at")).isAfter(now()))alert="EXPIRED";
            row.put("alert",alert);row.put("liveProviderRemaining",null);row.put("coverage","已接入的 AgentScope 模型路由请求；不含独立记忆、独立 RAG、探测、站外及未接入的历史调用");
        }return rows;}
    public record Policy(String modelId,Long totalTokens,int warningPercent,OffsetDateTime expiresAt,int expectedVersion){}
    public void policy(Policy request){var actor=lockedSupervisor();validate(request.modelId());if(request.totalTokens()!=null&&(request.totalTokens()<0||request.totalTokens()>1_000_000_000_000L)||request.warningPercent()<1||request.warningPercent()>100||request.expectedVersion()<0)throw new BusinessException(400,"额度参数不正确");ensure(request.modelId());var row=row("SELECT version FROM agent_model_budget WHERE model_id=? FOR UPDATE",request.modelId());int version=((Number)row.get("version")).intValue();if(request.expectedVersion()!=version&&!(request.expectedVersion()==0&&version==1))throw new BusinessException(409,"额度配置已更新，请重新读取");jdbc.update("UPDATE agent_model_budget SET total_tokens=?,warning_percent=?,expires_at=?,free_only=TRUE,version=version+1,updated_by=?,updated_at=? WHERE model_id=?",request.totalTokens(),request.warningPercent(),request.expiresAt()==null?null:request.expiresAt().withOffsetSameInstant(ZoneOffset.UTC).toLocalDateTime(),actor.userId(),now(),request.modelId());audit(actor.userId(),request.modelId(),"POLICY",version+1,Map.of("totalTokens",Objects.toString(request.totalTokens(),"UNKNOWN"),"warningPercent",request.warningPercent(),"freeOnly",true));}
    public record Observation(String modelId,Long remainingTokens,OffsetDateTime observedAt,String sourceNote,String requestId){}
    public void observe(Observation request){var actor=lockedSupervisor();validate(request.modelId());if(request.remainingTokens()==null||request.remainingTokens()<0||request.remainingTokens()>1_000_000_000_000L||request.observedAt()==null||request.observedAt().toInstant().isAfter(Instant.now().plusSeconds(60))||request.sourceNote()==null||request.sourceNote().isBlank()||request.sourceNote().length()>500||request.requestId()==null||!request.requestId().matches("[A-Za-z0-9_-]{8,64}"))throw new BusinessException(400,"供应商核对记录不正确");ensure(request.modelId());row("SELECT version FROM agent_model_budget WHERE model_id=? FOR UPDATE",request.modelId());String digest=sha(write(request));var repeated=rows("SELECT request_sha256 FROM agent_model_budget_observation WHERE actor_user_id=? AND request_id=?",actor.userId(),request.requestId());if(!repeated.isEmpty()){if(!digest.equals(repeated.get(0).get("request_sha256")))throw new BusinessException(409,"请求编号已用于其他核对记录");return;}jdbc.update("INSERT INTO agent_model_budget_observation(model_id,remaining_tokens,observed_at,source_note,actor_user_id,request_id,request_sha256,created_at) VALUES(?,?,?,?,?,?,?,?)",request.modelId(),request.remainingTokens(),request.observedAt().withOffsetSameInstant(ZoneOffset.UTC).toLocalDateTime(),request.sourceNote().strip(),actor.userId(),request.requestId(),digest,now());audit(actor.userId(),request.modelId(),"OBSERVATION",0,Map.of("remainingTokens",request.remainingTokens(),"observedAt",request.observedAt().toString()));}
    public List<Map<String,Object>> observations(String id){supervisor();validate(id);return rows("SELECT remaining_tokens,observed_at,source_note,actor_user_id,created_at FROM agent_model_budget_observation WHERE model_id=? ORDER BY observed_at DESC,id DESC LIMIT 100",id);}
    public void started(String attemptId,String modelId){ensure(modelId);var row=row("SELECT * FROM agent_model_budget WHERE model_id=? FOR UPDATE",modelId);var latest=rows("SELECT remaining_tokens FROM agent_model_budget_observation WHERE model_id=? ORDER BY observed_at DESC,id DESC LIMIT 1",modelId);if(!latest.isEmpty()&&((Number)latest.get(0).get("remaining_tokens")).longValue()==0)throw new Exhausted("该模型最近核对的免费额度已耗尽，请先核对供应商额度");if(date(row.get("expires_at"))!=null&&!date(row.get("expires_at")).isAfter(now()))throw new Exhausted("该模型登记的免费额度已到期");Long total=number(row.get("total_tokens"));if(total!=null){Long consumed=jdbc.queryForObject("SELECT COALESCE(SUM(COALESCE(input_tokens,0)+COALESCE(output_tokens,0)),0) FROM agent_model_budget_attempt WHERE model_id=?",Long.class,modelId);if(consumed>=total)throw new Exhausted("该模型已达到本站登记的额度上限");}jdbc.update("INSERT INTO agent_model_budget_attempt(attempt_id,model_id,status,started_at) VALUES(?,?,'STARTED',?)",attemptId,modelId,now());}
    public void finished(String attemptId,Map<String,Object> fields){try{Long input=number(fields.get("inputTokens")),output=number(fields.get("outputTokens")),cached=number(fields.get("cachedTokens"));String status=Objects.toString(fields.get("status"),"FAILED");if(!Set.of("COMPLETED","FAILED","CANCELLED").contains(status))throw new IllegalArgumentException();int changed=jdbc.update("UPDATE agent_model_budget_attempt SET status=?,input_tokens=?,output_tokens=?,cached_tokens=?,finished_at=? WHERE attempt_id=? AND model_id=? AND status='STARTED'",status,input,output,cached,now(),attemptId,fields.get("modelId"));if(changed!=1 && jdbc.queryForObject("SELECT COUNT(*) FROM agent_model_budget_attempt WHERE attempt_id=?",Long.class,attemptId)>0)throw new IllegalStateException("模型额度记录终态未核对");}catch(RuntimeException error){throw new ModelAttemptTrace.RecordingException();}}
    private void audit(long actor,String id,String action,int version,Object detail){jdbc.update("INSERT INTO agent_model_budget_audit(model_id,actor_user_id,action_name,version,detail_json,created_at) VALUES(?,?,?,?,?,?)",id,actor,action,version,write(detail),now());}
    private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception error){throw new IllegalStateException(error);}}
    private static String sha(String value){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception error){throw new IllegalStateException(error);}}
    private static Long number(Object value){if(!(value instanceof Number number))return null;long result=number.longValue();if(result<0)return null;return result;}
}
